var Ids=require("ids").default;export default function newDiagram(){function n(n){return new Ids([32,32,1]).nextPrefixed(n)}var e=n("Process_"),m=n("StartEvent_"),t=n("SequenceFlow_"),i=n("EndEvent_");return`<?xml version="1.0" encoding="UTF-8"?>\n<bpmn:definitions\n    xmlns="http://www.omg.org/spec/BPMN/20100524/MODEL"\n    xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"\n    xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"\n    xmlns:omgdc="http://www.omg.org/spec/DD/20100524/DC"\n    xmlns:omgdi="http://www.omg.org/spec/DD/20100524/DI"\n    xmlns:camunda="http://camunda.org/schema/1.0/bpmn"\n    xmlns:xsd="http://www.w3.org/2001/XMLSchema"\n    xmlns:flowable="http://flowable.org/bpmn"\n    xmlns:oplus="http://famessoft.com/schema/1.0/bpmn"\n    xmlns:ns0="undefined" \n    targetNamespace="http://www.flowable.org/processdef">\n    <bpmn:process id="${e}" isExecutable="true">\n        <bpmn:startEvent id="${m}">\n            <bpmn:outgoing>${t}</bpmn:outgoing>\n        </bpmn:startEvent>\n        <bpmn:sequenceFlow id="${t}" sourceRef="${m}" targetRef="${i}"></bpmn:sequenceFlow>\n        <bpmn:endEvent id="${i}">\n            <bpmn:incoming>${t}</bpmn:incoming>\n        </bpmn:endEvent>\n    </bpmn:process>\n    <bpmndi:BPMNDiagram id="BPMNDiagram_${e}">\n        <bpmndi:BPMNPlane id="BPMNPlane_${e}" bpmnElement="${e}">\n            <bpmndi:BPMNShape id="BPMNShape_${m}" bpmnElement="${m}">\n                <omgdc:Bounds x="150" y="200" width="36" height="36" />\n                <bpmndi:BPMNLabel>\n                    <omgdc:Bounds x="146" y="243" width="43" height="14" />\n                </bpmndi:BPMNLabel>\n            </bpmndi:BPMNShape>\n            <bpmndi:BPMNEdge id="BPMNEdge_${t}" bpmnElement="${t}">\n                <omgdi:waypoint x="186" y="218" />\n                <omgdi:waypoint x="760" y="218" />\n            </bpmndi:BPMNEdge>\n            <bpmndi:BPMNShape id="BPMNShape_${i}" bpmnElement="${i}">\n                <omgdc:Bounds x="760" y="200" width="36" height="36" />\n                <bpmndi:BPMNLabel>\n                    <omgdc:Bounds x="756" y="243" width="43" height="14" />\n                </bpmndi:BPMNLabel>\n            </bpmndi:BPMNShape>\n        </bpmndi:BPMNPlane>\n    </bpmndi:BPMNDiagram>\n</bpmn:definitions>`}